The following Terraform configuration creates an AWS Chime SDK Voice Connector and enables media streaming for it to Amazon Kinesis Video Streams. It also creates an example Kinesis Video Stream with retention configured, along with the required AWS provider configuration and default variables.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "voice_connector_name" {
  description = "Name of the AWS Chime SDK Voice Connector."
  type        = string
  default     = "example-chime-voice-connector"
}

variable "kinesis_video_stream_name" {
  description = "Name of the Amazon Kinesis Video Stream for media streaming."
  type        = string
  default     = "example-chime-media-stream"
}

variable "media_retention_hours" {
  description = "Retention period in hours for the Kinesis Video Stream."
  type        = number
  default     = 24
}

